"""Keep generated files and the legacy Make adaptations inside Bazel outputs."""

import argparse
import json
import os
from pathlib import Path
import runpy
import shlex
import shutil
import subprocess
import sys


def generate(script, arguments):
    # Generated bytecode is not an upstream source input.
    sys.dont_write_bytecode = True
    script = Path(script).resolve()
    sys.path.insert(0, str(script.parent))
    sys.argv = [str(script), *arguments]
    runpy.run_path(str(script), run_name="__main__")


def replace_exact(path, old, new):
    text = path.read_text()
    if old not in text:
        raise ValueError(f"Expected Make recipe changed in {path}: {old!r}")
    path.write_text(text.replace(old, new))


def prepare(args):
    output = Path(args.output).resolve()
    for source, relative in json.loads(Path(args.manifest).read_text()):
        destination = (output / relative).resolve()
        if not destination.is_relative_to(output):
            raise ValueError(f"Source escapes staged tree: {relative}")
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, destination)
        shutil.copymode(source, destination)
        destination.chmod(destination.stat().st_mode | 0o200)

    pipeline = output / "dash-pipeline"
    result = pipeline / "bmv2/dash_pipeline.bmv2"
    result.mkdir(parents=True)
    subprocess.run([
        str(Path(args.p4c).resolve()), "-DTARGET_BMV2_V1MODEL",
        "bmv2/dash_pipeline.p4", "-o", str(result / "dash_pipeline.json"),
        "--p4runtime-files", str(result / "dash_pipeline_p4rt.json") + "," + str(result / "dash_pipeline_p4rt.txt"),
        "--toJSON", str(result / "dash_pipeline_ir.json"),
    ], cwd=pipeline, check=True)

    sai = pipeline / "SAI"
    # The top-level Make sai-headers target creates this output directory
    # before invoking SAI/Makefile's multi-source install recipe.
    (sai / "lib").mkdir()
    # The original Make default uses /bmv2. Relocate only our private copy;
    # keep the checked-in Make recipe and its generator arguments unchanged.
    replace_exact(sai / "Makefile", "/bmv2/", str(pipeline / "bmv2") + "/")
    command = shlex.quote(str(Path(args.launcher).resolve())) + " generate " + shlex.quote(str(sai / "sai_api_gen.py"))
    replace_exact(sai / "Makefile", "./sai_api_gen.py", command)
    env = os.environ.copy()
    env["PATH"] = str(Path(args.tool_runtime).resolve() / "bin")
    subprocess.run([str(Path(args.make).resolve()), "all"], cwd=sai, env=env, check=True)

    # Match buildimage's existing metadata recipe; these checks assume an
    # unextended upstream SAI checkout and are already skipped by native Make.
    metadata_make = sai / "SAI/meta/Makefile"
    lines = metadata_make.read_text().splitlines(keepends=True)
    omitted = ("checkenumlock.sh", "checkancestry.sh", "checkstructs.sh", "./saimetadatatest >/dev/null")
    metadata_make.write_text("".join(line for line in lines if not any(item in line for item in omitted)))
    replace_exact(metadata_make, "nm ", "$(NM) ")
    # Upstream hardcodes g++. Use the selected Bazel compiler and its flags in
    # this private copy; source, warnings and compile/install targets are kept.
    replace_exact(sai / "lib/Makefile", "g++ ", "$(CXX) ")
    replace_exact(sai / "lib/Makefile", "-shared -g -o $@ $^", "-shared -g -o $@ $^ $(LDFLAGS) $(LIBS)")


def main():
    if len(sys.argv) > 1 and sys.argv[1] == "generate":
        generate(sys.argv[2], sys.argv[3:])
        return
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["prepare"])
    for name in ["manifest", "output", "p4c", "launcher", "make", "tool-runtime"]:
        parser.add_argument("--" + name, required=True)
    prepare(parser.parse_args())


if __name__ == "__main__":
    main()
